import json, sys, html as _h

BOOK = {'title': 'Neon and Blood', 'author': 'Signature original', 'genre': 'Missing Persons', 'chapters': [{'n': 1, 'title': 'The Client', 'text': "That night Eddie Cross stood at the office window, watching the neon bleed into the wet street. a key to a locker sat in the safe. Outside, Neon Row did what it always did: it waited.\n\n'I need you to find out what this means,' the client said, laying a key to a locker on the desk like a bet. Eddie Cross had seen a hundred such objects. They all meant the same thing: somebody was lying, and somebody was going to bleed.\n\nEddie Cross took the case. Not for the money — the money was insulting — but because a key to a locker had a look Eddie Cross recognized: the look of the one honest thing in a dirty town."}, {'n': 2, 'title': 'The Streets Talk', 'text': "The address led to Neon Row's underbelly — a locker, a ledger, a man who didn't want to talk until Eddie Cross showed him a key to a locker. Then he talked like a river, and Eddie Cross wrote it all down.\n\nRuby sang the late set and slipped Eddie Cross a note between songs: a name, an address, a warning. 'They're watching you now,' she breathed. Eddie Cross tipped her and meant it.\n\nBack at the office, Eddie Cross spread the pieces out: a key to a locker, the ledger page, Ruby's note. The shape of it was the dame with the red scarf, big as a building. And Eddie Cross was just one detective with a gun and a grudge against lies."}, {'n': 3, 'title': "The Dame's Story", 'text': "They tailed the dame with the red scarf's fixer to a warehouse on the waterfront. What they saw there turned Eddie Cross's stomach: not just money, but the machinery of Neon Row's misery, oiled and humming.\n\nMaggie the reporter didn't like it. 'Dames,' Maggie the reporter said, 'are how detectives get killed.' Eddie Cross agreed and kept the case anyway. Some habits are stronger than sense.\n\n'Why should I trust you?' Eddie Cross asked. She had no answer that wasn't tears, and Eddie Cross had stopped buying tears during the war. But a key to a locker was real, and the ledger was real, and that was enough."}, {'n': 4, 'title': 'The Squeeze', 'text': "the dame with the red scarf squeezed back. First the office: tossed, the safe cracked, a key to a locker's copy gone — but Eddie Cross keeps the originals where no one looks. Then Maggie the reporter: a warning delivered with fists in an alley off Neon Row.\n\nThe dame vanished. Of course she did. Eddie Cross found her scarf in the office, red as a warning, and underneath it a note: 'Forgive me. They have my brother.' So that was the price. Everyone has one.\n\nMaggie the reporter showed up bloody and grinning. 'They hit like accountants,' Maggie the reporter said. Eddie Cross felt the cold anger settle in, the kind that doesn't shout, just aims."}, {'n': 5, 'title': 'The Confrontation', 'text': "'You're finished,' Eddie Cross said. the dame with the red scarf smiled the smile of someone who has bought judges. 'Am I?' Then Maggie the reporter opened the door with the district attorney, and Ruby, and the dame's brother, alive, and the smile died.\n\nThat night it rained again, washing Neon Row clean for an hour. Eddie Cross stood at the window with a key to a locker — the case closed, the ledger in the DA's hands. loyalty in a dirty town, Eddie Cross thought. Even here. Especially here.\n\nEddie Cross walked into the dame with the red scarf's office at noon, when Neon Row was bright and honest-looking, which made the lies inside seem darker. a key to a locker went on the desk. The photographs went on the desk. The truth went on the desk."}, {'n': 6, 'title': 'Last Call', 'text': "The phone rang. Eddie Cross picked it up. 'Eddie Cross Investigations,' Eddie Cross said, and listened, and smiled the thin smile of someone who knows exactly how much trouble costs. 'loyalty in a dirty town. I'll take the case.'\n\nLou poured a double on the house. Ruby sang the song she only sings when she means it. Maggie the reporter's ribs were taped, but Maggie the reporter drank anyway, doctor's orders being for other people.\n\na key to a locker went into the office safe, next to the other honest things. Someday, Eddie Cross knew, someone would walk in with something like it, and it would start again. It always starts again."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

